  const found = GMAIL_LABEL_ID_CACHE.get(name);
  if (found) return found;
  const created = await gmailFetch(env, "/labels", { method: "POST", body: JSON.stringify({ name, labelListVisibility: "labelShow", messageListVisibility: "show" }) });
